function encodeSvgDataUri(svg: string): string {
  if (typeof window !== "undefined" && typeof window.btoa === "function") {
    return `data:image/svg+xml;base64,${window.btoa(unescape(encodeURIComponent(svg)))}`;
  }
  return `data:image/svg+xml;base64,${Buffer.from(svg).toString("base64")}`;
}

function escapeXml(unsafe: string): string {
  return unsafe
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

export function createAnimeHeroSvg(profile: ReadmeProfileData, config: ReadmeConfig): string {
  const name = escapeXml(profile.name || profile.username || "Shinobi Developer");
  const username = escapeXml(profile.username || "shinobi");
  const repos = String(profile.publicRepos ?? config.featuredRepos?.repos?.length ?? 24);
  const totalStars = config.featuredRepos?.repos?.reduce((acc, r) => acc + (r.stars || 0), 0) || 0;
  const stars = totalStars > 0 ? `${totalStars}+` : "15+";
  const followers = String(profile.followers ?? 42);

  // Compute 4 dynamic roles from user headline, skills, or top languages
  const topLangs = profile.topLanguages?.map((l) => l.name) || [];
  const chosenSkills = config.skills?.selectedSkills || [];
  const role1 = escapeXml(config.header?.role || "Full Stack Developer");
  const role2 = escapeXml(topLangs[0] ? `${topLangs[0]} & Systems Shinobi` : "Software Engineer");
  const role3 = escapeXml(chosenSkills[0] ? `${chosenSkills[0]} Specialist` : "Open Source Builder");
  const role4 = escapeXml(topLangs[1] ? `${topLangs[1]} & Web Arch` : "Production Systems");

  // Format bio into 2 lines
  const rawBio = config.header?.tagline || profile.bio || "Turning online energy into fast, cinematic web experiences — one commit at a time.";
  const cleanBio = rawBio.replace(/\r?\n/g, " ").trim();
  let bio1 = cleanBio;
  let bio2 = "";
  if (cleanBio.length > 55) {
    const splitIdx = cleanBio.lastIndexOf(" ", 52);
    if (splitIdx > 20) {
      bio1 = cleanBio.substring(0, splitIdx).trim();
      bio2 = cleanBio.substring(splitIdx).trim();
      if (bio2.length > 55) bio2 = bio2.substring(0, 52) + "...";
    } else {
      bio1 = cleanBio.substring(0, 50) + "...";
    }
  }
  bio1 = escapeXml(bio1);
  bio2 = escapeXml(bio2);

  let svg = ANIME_HERO_TEMPLATE;

  // Replace all occurrences of Megha Mittal in title, aria-label, and heading text
  svg = svg.replaceAll("Megha Mittal", name);

  // Replace terminal prompt
  svg = svg.replace("shinobi@konoha", `${username}@konoha`);

  // Replace roles
  svg = svg.replace('>Frontend Developer<', `>${role1}<`);
  svg = svg.replace('>Anime Web Experiences<', `>${role2}<`);
  svg = svg.replace('>Motion &amp; GSAP Specialist<', `>${role3}<`);
  svg = svg.replace('>SQL &amp; SAP Workflows<', `>${role4}<`);

  // Replace Bio
  svg = svg.replace(
    'Turning anime energy into fast, cinematic web',
    bio1
  );
  svg = svg.replace(
    'experiences &#8212; one commit at a time.',
    bio2 || "experiences &#8212; one commit at a time."
  );

  // Replace stats
  svg = svg.replace(/<text class="sg" x="70" y="428" font-size="22" fill="#ff7a1a">32<\/text>/g, `<text class="sg" x="70" y="428" font-size="22" fill="#ff7a1a">${repos}</text>`);
  svg = svg.replace(/<text class="sg" x="202" y="428" font-size="22" fill="#ff7a1a">396\+<\/text>/g, `<text class="sg" x="202" y="428" font-size="22" fill="#ff7a1a">${stars}</text>`);
  svg = svg.replace(/<text class="sg" x="334" y="428" font-size="22" fill="#ff7a1a">420<\/text>/g, `<text class="sg" x="334" y="428" font-size="22" fill="#ff7a1a">${followers}</text>`);

  return encodeSvgDataUri(svg);
}

export function createAnimeNinjaWaySvg(profile: ReadmeProfileData, config: ReadmeConfig): string {
  const { aboutMe, featuredRepos } = config;
  const username = escapeXml(profile.username || "shinobi");
  const repos = String(profile.publicRepos ?? featuredRepos?.repos?.length ?? 24);
  const totalStars = featuredRepos?.repos?.reduce((acc, r) => acc + (r.stars || 0), 0) || 0;
  const stars = totalStars > 0 ? `${totalStars}+` : "15+";
  const followers = String(profile.followers ?? 42);

  const headline = escapeXml(config.header?.role || "Developer & Open Source Builder");
  const subtitle = escapeXml(profile.company ? `Engineer at ${profile.company} by day, open source builder by night.` : "Code artisan by day, high-velocity builder by night.");

  let svg = ANIME_NINJA_WAY_TEMPLATE;

  svg = svg.replace("Frontend developer at Wiley by day, anime-web builder by night.", subtitle);

  // Dynamic Pillar 1
  if (aboutMe?.workingOn) {
    svg = svg.replace("Interfaces that feel alive", "Active Summons &amp; Builds");
    svg = svg.replace("Responsive, pixel-perfect builds in HTML, CSS, JavaScript &amp; React", escapeXml(aboutMe.workingOn.slice(0, 68)));
  } else {
    svg = svg.replace("Interfaces that feel alive", headline);
  }

  // Dynamic Pillar 2
  if (aboutMe?.learning) {
    svg = svg.replace("Motion with a story arc", "Jutsu Deep Dive &amp; Research");
    svg = svg.replace("Scroll-driven scenes, transitions and micro-interactions with GSAP", escapeXml(aboutMe.learning.slice(0, 68)));
  }

  // Dynamic Pillar 3
  if (aboutMe?.collaborateOn) {
    svg = svg.replace("Enterprise-grade plumbing", "Joint Squad Missions");
    svg = svg.replace("SQL queries and SAP-integrated business flows that hold up in production", escapeXml(aboutMe.collaborateOn.slice(0, 68)));
  } else if (aboutMe?.askMeAbout) {
    svg = svg.replace("Enterprise-grade plumbing", "Consultation &amp; Inquiries");
    svg = svg.replace("SQL queries and SAP-integrated business flows that hold up in production", escapeXml(aboutMe.askMeAbout.slice(0, 68)));
  }

  // Dynamic footer quote stats
  svg = svg.replace(
    "NIND&#332; &#183; 32 REPOS &#183; 396+ STARS &#183; 420 FOLLOWERS",
    `NIND&#332; &#183; ${repos} REPOS &#183; ${stars} STARS &#183; ${followers} FOLLOWERS &#183; @${username}`
  );

  return encodeSvgDataUri(svg);
}

export function createAnimeJutsuStackSvg(profile: ReadmeProfileData, config: ReadmeConfig): string {
  const skillsList = config.skills?.selectedSkills || [];
  const topLangs = profile.topLanguages?.map((l) => l.name) || [];

  // Combine top languages and selected skills
  const combined = Array.from(new Set([...topLangs, ...skillsList]));
  const defaultStack = [
    "HTML5", "CSS3", "JavaScript", "TypeScript", "React",
    "Node.js", "Python", "Rust", "Go", "SQL",
    "Docker", "Git", "GitHub", "Linux", "Next.js"
  ];
  const finalStack = combined.length >= 5 ? combined.slice(0, 15) : defaultStack;
  while (finalStack.length < 15) {
    finalStack.push(defaultStack[finalStack.length]);
  }

  let svg = ANIME_JUTSU_STACK_TEMPLATE;

  // Replace default chip labels with the user's actual technologies
  const origChips = [
    "HTML5", "CSS3", "JavaScript", "TypeScript", "React",
    "Bootstrap", "GSAP", "Framer", "Three.js", "SQL",
    "SAP", "Git", "GitHub", "Claude", "Copilot"
  ];

  origChips.forEach((orig, idx) => {
    const userTech = escapeXml(finalStack[idx] || orig);
    svg = svg.replace(`>${orig}<`, `>${userTech}<`);
  });

  // Replace counter title
  svg = svg.replace(
    "15 TECHNIQUES MASTERED",
    `${finalStack.length} TECHNIQUES MASTERED`
  );

  return encodeSvgDataUri(svg);
}

export function createAnimeNinjaIdSvg(profile: ReadmeProfileData, config: ReadmeConfig): string {
  const name = escapeXml(profile.name || profile.username || "Shinobi Developer");
  const username = escapeXml(profile.username || "shinobi");
  const repos = String(profile.publicRepos ?? config.featuredRepos?.repos?.length ?? 24);
  const totalStars = config.featuredRepos?.repos?.reduce((acc, r) => acc + (r.stars || 0), 0) || 0;
  const stars = totalStars > 0 ? `${totalStars}+` : "15+";
  const forks = String(config.featuredRepos?.repos?.reduce((acc, r) => acc + (r.forks || 0), 0) || 2);
  const followers = String(profile.followers ?? 42);
  const location = escapeXml(profile.location || "Leaf Village");
  const company = escapeXml(profile.company || "Independent Clan");
  const role = escapeXml(config.header?.role ? config.header.role.toUpperCase() : "FRONTEND SHINOBI");

  let svg = ANIME_NINJA_ID_TEMPLATE;

  // Replace user identification
  svg = svg.replaceAll("Megha Mittal", name);
  svg = svg.replaceAll("@Meghamittal0920", `@${username}`);
  svg = svg.replace("Noida, IN", location.slice(0, 18));
  svg = svg.replace("Wiley", company.slice(0, 18));
  svg = svg.replace("FRONTEND SHINOBI", role.slice(0, 22));

  // Replace user avatar if available
  if (profile.avatarUrl) {
    svg = svg.replace(
      /href="data:image\/jpeg;base64,[^"]+"/i,
      `href="${profile.avatarUrl}"`
    );
  }

  // Replace animated live stat counters
  svg = svg.replaceAll('fill="#eef1f7" opacity="1">32<', `fill="#eef1f7" opacity="1">${repos}<`);
  svg = svg.replaceAll('fill="#eef1f7" opacity="1">396+<', `fill="#eef1f7" opacity="1">${stars}<`);
  svg = svg.replaceAll('fill="#eef1f7" opacity="1">193+<', `fill="#eef1f7" opacity="1">${forks}<`);
  svg = svg.replaceAll('fill="#eef1f7" opacity="1">420<', `fill="#eef1f7" opacity="1">${followers}<`);

  // Replace Top Missions Bar Chart with the user's actual repositories & star counts!
  const reposList = config.featuredRepos?.repos?.filter(r => r.selected !== false) || [];
  const topRepos = reposList.slice(0, 5);
  const defaultRepoNames = ["itachi", "Meghamittal0920", "Naruto-SageMode", "Zoro-King-of-hell", "Minato", "Gojo"];
  const defaultRepoStars = [175, 83, 72, 23, 22, 21];

  topRepos.forEach((r, i) => {
    const origName = defaultRepoNames[i];
    const origStar = defaultRepoStars[i];
    if (origName) {
      svg = svg.replace(`>${origName}<`, `>${escapeXml(r.name.slice(0, 16))}<`);
      svg = svg.replace(`>${origStar}<`, `>${r.stars || 0}<`);
    }
  });

  return encodeSvgDataUri(svg);
}

export function createAnimeConnectSvg(profile: ReadmeProfileData, config: ReadmeConfig): string {
  const username = escapeXml(profile.username || "shinobi");
  const email = escapeXml(config.socials?.email || (profile.email ? profile.email : `${username}@users.noreply.github.com`));
  const instagram = escapeXml(config.socials?.instagram || `@${username}`);
  const twitter = escapeXml(config.socials?.twitter || `@${username}`);

  let svg = ANIME_CONNECT_TEMPLATE;
  svg = svg.replaceAll("Meghamittal0920", username);
  svg = svg.replaceAll("meghamittal563@gmail.com", email);
  svg = svg.replaceAll("@meghamittal92000", instagram);
  svg = svg.replaceAll("Threads", "Twitter / X");

  return encodeSvgDataUri(svg);
}
